// === Jarvis bot: error/alarm + symbols + interface (tra loi NGAN de nhanh) ===
const REG_URL = "https://raw.githubusercontent.com/ntvn2022/z-bee-duo/claude/esp32-s3-touch-screen-wwelt1/xiaozhi-ai/machines/registry.json";
const body = ($input.first().json.body) || $input.first().json || {};
const text = (body.text || "").toString().trim();
const MODEL = body.model || "gemini-2.5-flash";
const GEMINI_KEY = body.gemini_key || $env.GEMINI_API_KEY || "";
const out = (o) => [{ json: o }];
if (!text) return out({ reply: "Bạn hỏi lỗi/cảnh báo, ký hiệu hay chân tín hiệu của máy nào?", need:"text" });
if (/(k[eế]t th[uú]c robot|tho[aá]t robot|d[uừ]ng robot)/i.test(text))
  return out({ reply: "Đã thoát chế độ tra cứu lỗi máy.", mode:"exit" });

const norm=(s)=>(s||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"");
const t=norm(text);
const esc=(s)=>s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
const clean=(s)=>(s||"").replace(/[*#]/g,"").replace(/\s*\n\s*/g," ").replace(/\s{2,}/g," ").trim();
const GURL=`https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent?key=${GEMINI_KEY}`;
async function ask(prompt){ if(!GEMINI_KEY) return ""; try{
  const g=await this.helpers.httpRequest({method:"POST",url:GURL,json:true,body:{
    contents:[{parts:[{text:prompt}]}],
    generationConfig:{maxOutputTokens:220,temperature:0.3}
  }});
  return clean(g?.candidates?.[0]?.content?.parts?.[0]?.text||""); }catch(e){ return ""; } }

const registry=await this.helpers.httpRequest({url:REG_URL,json:true});
let machine=null,best=-1;
for(const m of registry) for(const a of (m.aliases||[])){const p=t.lastIndexOf(norm(a));if(p>best){best=p;machine=m;}}
if(!machine){ if(registry.length===1) machine=registry[0];
  else return out({reply:"Bạn hỏi về máy nào? Hiện có: "+registry.map(m=>m.name_vi).join(", ")+".",need:"machine"}); }
const rows=await this.helpers.httpRequest({url:machine.tables_url,json:true});

// SYMBOL / SIGNAL
const safe=(c)=>/\d/.test(c)||/^(FC|SP|SG|AL|ES|EJ|RY)/i.test(c);
let ref=null,rp=-1;
for(const r of rows){ if(r.type!=="symbol"&&r.type!=="signal") continue; if(!safe(r.code)) continue;
  const p=t.search(new RegExp("\\b"+esc(r.code.toLowerCase())+"\\b")); if(p>=0&&p>rp){rp=p;ref=r;} }
if(ref){
  let reply=await ask.call(this,`Giải thích ký hiệu "${ref.code}" của ${machine.name_vi} trong ĐÚNG 1 câu ngắn tiếng Việt, văn xuôi trơn, không markdown. Dữ liệu: ${ref.code} = ${ref.content}`);
  if(!reply) reply=`${ref.code}: ${clean(ref.content)}`;
  return out({reply,machine:machine.id,symbol:ref.code,kind:ref.type});
}
// CABLE
if(/\b(day|cap|cable|chan)\b/.test(t)){
  const mm=t.match(/\d{1,2}/);
  if(mm){ const cab=rows.find(r=>r.type==="cable"&&parseInt(r.code,10)===parseInt(mm[0],10));
    if(cab){ let reply=await ask.call(this,`Dây tín hiệu số ${cab.code} của ${machine.name_vi} là gì? Trả lời 1 câu ngắn tiếng Việt. Dữ liệu: dây ${cab.code} = ${cab.content}`);
      if(!reply) reply=`Dây tín hiệu số ${cab.code}: ${clean(cab.content)}`;
      return out({reply,machine:machine.id,cable:cab.code,kind:"cable"}); } } }

// ERROR / ALARM
const errT=machine.error_types||[],almT=machine.alarm_types||[];
const nums=t.match(/\d{1,3}/g);
if(!nums) return out({reply:`Bạn hỏi mã lỗi/cảnh báo số mấy, hay ký hiệu/chân nào của ${machine.name_vi}?`,need:"code"});
const num=parseInt(nums[nums.length-1],10);
const ia=Math.max(t.lastIndexOf("alarm"),t.lastIndexOf("canh bao")), ie=Math.max(t.lastIndexOf("error"),t.lastIndexOf("loi"));
const wantAlarm=ia>=0&&ia>ie, wantError=ie>=0&&ie>ia;
const matches=rows.filter(r=>(errT.includes(r.type)||almT.includes(r.type))&&parseInt(r.code,10)===num);
if(!matches.length) return out({reply:`Không thấy mã ${num} cho ${machine.name_vi}. Bạn kiểm tra lại số nhé.`,need:"code"});
const grp=(ty)=>errT.includes(ty)?"error":(almT.includes(ty)?"alarm":"other");
const hasErr=matches.some(m=>grp(m.type)==="error"),hasAlm=matches.some(m=>grp(m.type)==="alarm");
let selected=matches,askType=false;
if(wantError&&!wantAlarm) selected=matches.filter(m=>grp(m.type)==="error");
else if(wantAlarm&&!wantError) selected=matches.filter(m=>grp(m.type)==="alarm");
else if(hasErr&&hasAlm) askType=true;
if(!selected.length) selected=matches;
const ctx=selected.map(m=>`[${m.type} ${m.code}] ${m.content}`).join("\n");
let s=`Bạn là trợ lý kỹ thuật cho ${machine.name_vi}. Trả lời tiếng Việt RẤT NGẮN GỌN, TỐI ĐA 2 câu: câu 1 mô tả+nguyên nhân gộp lại; câu 2 cách khắc phục. Văn xuôi trơn, không markdown, không đánh số, không lặp lại. `;
if(askType) s+=`Mã ${num} có ở cả cảnh báo (alarm) lẫn lỗi (error) — nêu gọn cả hai rồi hỏi lại muốn loại nào. `;
s+=`Thêm đúng 1 câu cuối thật ngắn: "Lưu ý phân biệt alarm và error." CHỈ dùng dữ liệu:\n${ctx}`;
let reply=await ask.call(this,s+`\n\nHỏi: ${text}`);
if(!reply) reply=selected.map(m=>`${m.type} ${m.code}: ${m.content}`).join(" | ")+" (alarm khác error).";
return out({reply,machine:machine.id,code:num,types:selected.map(m=>m.type),askType});
